import { RequirementNode, Student } from "./types";

/**
 * Fixture 1: L&S 7-Course Breadth.
 *
 * Shape: a flat AND of 7 tag-leaves. Simplest possible tree -- good for
 * sanity-checking basic AND handling before anything nested.
 */
export const breadthRequirement: RequirementNode = {
  type: "and",
  label: "L&S 7-Course Breadth",
  children: [
    { type: "tag", tag: "arts_and_literature", label: "Arts & Literature" },
    { type: "tag", tag: "biological_science", label: "Biological Science" },
    { type: "tag", tag: "historical_studies", label: "Historical Studies" },
    { type: "tag", tag: "international_studies", label: "International Studies" },
    { type: "tag", tag: "philosophy_and_values", label: "Philosophy & Values" },
    { type: "tag", tag: "physical_science", label: "Physical Science" },
    { type: "tag", tag: "social_and_behavioral_sciences", label: "Social & Behavioral Sciences" },
  ],
};

/**
 * Fixture 2: CS Major Requirements.
 *
 * Shape: AND of [3 required courses, an OR (lab equivalency), an N-of-M
 * (electives), an OR of ANDs (track requirement)] -- 3 levels of nesting via
 * the track requirement (and > or > and).
 *
 * Note COMPSCI 162 appears BOTH as one of the 5 elective options AND inside
 * the Systems Track. This is intentional and realistic (a course can count
 * toward more than one degree requirement at once) -- completing 162 should
 * be able to help satisfy the electives N-of-M *and* the Systems Track
 * simultaneously; it is not "used up" by whichever one is checked first.
 */
export const csMajorRequirement: RequirementNode = {
  type: "and",
  label: "CS Major Requirements",
  children: [
    { type: "course", courseId: "COMPSCI 61A", label: "CS 61A" },
    { type: "course", courseId: "COMPSCI 61B", label: "CS 61B" },
    { type: "course", courseId: "COMPSCI 70", label: "CS 70" },
    {
      type: "or",
      label: "Machine Structures Lab",
      children: [
        { type: "course", courseId: "COMPSCI 61C", label: "CS 61C" },
        { type: "course", courseId: "COMPSCI 61CL", label: "CS 61CL" },
      ],
    },
    {
      type: "n_of_m",
      n: 3,
      label: "3 of 5 Upper-Division Electives",
      children: [
        { type: "course", courseId: "COMPSCI 161", label: "CS 161 (Security)" },
        { type: "course", courseId: "COMPSCI 162", label: "CS 162 (Operating Systems)" },
        { type: "course", courseId: "COMPSCI 170", label: "CS 170 (Algorithms)" },
        { type: "course", courseId: "COMPSCI 186", label: "CS 186 (Databases)" },
        { type: "course", courseId: "COMPSCI 188", label: "CS 188 (AI)" },
      ],
    },
    {
      type: "or",
      label: "Track Requirement",
      children: [
        {
          type: "and",
          label: "AI Track",
          children: [
            { type: "course", courseId: "COMPSCI 189", label: "CS 189 (ML)" },
            { type: "course", courseId: "COMPSCI 182", label: "CS 182 (Deep Learning)" },
          ],
        },
        {
          type: "and",
          label: "Systems Track",
          children: [
            { type: "course", courseId: "COMPSCI 152", label: "CS 152 (Computer Architecture)" },
            { type: "course", courseId: "COMPSCI 162", label: "CS 162 (Operating Systems)" },
          ],
        },
      ],
    },
  ],
};

/**
 * Fixture 3: Global Awareness (2 of 3 areas), by TAG rather than specific
 * course, and with only 3 children -- kept small on purpose so the
 * double-counting edge case is easy to reason about by hand.
 */
export const globalAwarenessRequirement: RequirementNode = {
  type: "n_of_m",
  n: 2,
  label: "2 of 3 Global Awareness Areas",
  children: [
    { type: "tag", tag: "writing_intensive", label: "Writing Intensive" },
    { type: "tag", tag: "global_perspectives", label: "Global Perspectives" },
    { type: "tag", tag: "quantitative_reasoning", label: "Quantitative Reasoning" },
  ],
};

/**
 * Small dedicated fixture for the "same course, two different leaves, two
 * different branches" case. Unlike the n_of_m dedup case above, this is an
 * AND -- ANDs and ORs never count "how many", so the same physical course
 * satisfying both leaves here is fine and both should show as satisfied.
 */
export const crossBranchRequirement: RequirementNode = {
  type: "and",
  label: "Two independent checks on the same course",
  children: [
    { type: "course", courseId: "COMPSCI 61B", label: "CS 61B (specific)" },
    { type: "tag", tag: "programming_intensive", label: "Any programming-intensive course" },
  ],
};

